<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'

const rows = ref<any[]>([])
const loading = ref(false)
const detailLoading = ref(false)
const saving = ref(false)
const detailOpen = ref(false)
const detail = ref<any | null>(null)
const form = ref({ status: '', reviewComment: '', sampleFeeYuan: '', sampleLeadTime: '', sampleMaterial: '', sampleQuoteNote: '' })

function orderTypeText(r: any) { return r.orderType === 'professional' ? '专业作品打样' : r.orderType === 'multiview' ? '多视图打样' : r.orderType === 'model' ? '3D模型打样' : '生产申请' }
function textStatus(r: any) { if (r.samplePaymentStatus === 'paid' || (r.orderType === 'professional' && r.status === 'processing')) return '已支付打样费 · 生产中'; if (r.samplePaymentStatus === 'unpaid') return '待用户支付打样费'; if (r.samplePaymentStatus === 'pending') return '支付处理中'; if (r.samplePaymentStatus === 'manual_review') return '待管理员核验'; return r.status === 'review' ? '待审核' : r.status === 'processing' ? '生产中' : r.status || '-' }
function formatTime(value: any) { return value ? String(value).replace('T', ' ').slice(0, 19) : '-' }
function money(value: any) { return value == null || value === '' ? '-' : `¥${Number(value).toFixed(2)}` }
function fileSize(value: any) { const bytes = Number(value || 0); return bytes > 1024 * 1024 ? `${(bytes / 1024 / 1024).toFixed(1)} MB` : bytes ? `${Math.ceil(bytes / 1024)} KB` : '-' }
function typeFor(row: any) { return String(row?.orderType || row?.requestType || '') === 'professional' ? 'professional' : String(row?.orderType || row?.requestType || 'production') }
function detailTitle() { return detail.value?.title || detail.value?.productName || detail.value?.assetTitle || detail.value?.originalName || '订单详情' }
const isProfessional = computed(() => detail.value?.detailType === 'professional_submission')
const canEditQuote = computed(() => Boolean(detail.value && !['paid', 'pending', 'manual_review'].includes(String(detail.value.samplePaymentStatus || ''))))

async function load() { loading.value = true; try { const response = await fetch('/api/creative/ai/admin/orders?size=500', { cache: 'no-store' }); rows.value = response.ok ? await response.json() : [] } finally { loading.value = false } }

async function openDetail(row: any) {
  detailLoading.value = true; detailOpen.value = true; detail.value = null
  try {
    const response = await fetch(`/api/creative/ai/admin/orders/${encodeURIComponent(typeFor(row))}/${encodeURIComponent(row.id)}`, { cache: 'no-store' })
    const data = await response.json().catch(() => null)
    if (!response.ok) throw new Error(data?.message || `HTTP ${response.status}`)
    detail.value = data
    form.value = { status: String(data.status || ''), reviewComment: String(data.reviewComment || ''), sampleFeeYuan: data.sampleFeeYuan == null ? '' : String(data.sampleFeeYuan), sampleLeadTime: String(data.sampleLeadTime || data.quotedSampleLeadTime || ''), sampleMaterial: String(data.sampleMaterial || ''), sampleQuoteNote: String(data.sampleQuoteNote || data.quotedSampleNote || '') }
  } catch (error: any) { detailOpen.value = false; window.alert(`读取订单详情失败：${error.message || error}`) } finally { detailLoading.value = false }
}

async function saveDetail() {
  if (!detail.value || saving.value) return
  saving.value = true
  try {
    const id = detail.value.id
    if (isProfessional.value) {
      const response = await fetch(`/api/creative/ai/consumer-professional-submissions/${id}/review`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ status: form.value.status || detail.value.status || 'review', comment: form.value.reviewComment, quotedSampleFeeYuan: form.value.sampleFeeYuan, quotedSampleLeadTime: form.value.sampleLeadTime, quotedSampleNote: form.value.sampleQuoteNote }) })
      const data = await response.json().catch(() => null); if (!response.ok) throw new Error(data?.message || `HTTP ${response.status}`)
    } else {
      const requestType = String(detail.value.requestType || '')
      if (requestType === 'sample' && form.value.status === 'approved' && form.value.sampleFeeYuan.trim()) {
        const response = await fetch(`/api/creative/ai/consumer-production/admin/${id}/quote`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ sampleFeeYuan: form.value.sampleFeeYuan, sampleLeadTime: form.value.sampleLeadTime, sampleMaterial: form.value.sampleMaterial, sampleQuoteNote: form.value.sampleQuoteNote, reviewComment: form.value.reviewComment }) })
        const data = await response.json().catch(() => null); if (!response.ok) throw new Error(data?.message || `HTTP ${response.status}`)
      }
      if (form.value.status && form.value.status !== detail.value.status && !(form.value.status === 'approved' && form.value.sampleFeeYuan.trim())) {
        const response = await fetch(`/api/creative/ai/consumer-production/admin/${id}/review`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ status: form.value.status, comment: form.value.reviewComment }) })
        const data = await response.json().catch(() => null); if (!response.ok) throw new Error(data?.message || `HTTP ${response.status}`)
      }
    }
    await load(); await openDetail({ id, orderType: detail.value.orderType || detail.value.requestType }); window.alert('订单信息已保存')
  } catch (error: any) { window.alert(`保存订单信息失败：${error.message || error}`) } finally { saving.value = false }
}
function closeDetail() { detailOpen.value = false; detail.value = null }
</script>

<template>
  <div class="orders-page">
    <header><div><span>ORDER CENTER</span><h1>订单管理</h1><p>统一查看图片、3D 模型、多视图和专业作品的打样与生产阶段。</p></div><button @click="load" :disabled="loading">{{ loading ? '加载中…' : '刷新' }}</button></header>
    <div class="table-wrap"><table><thead><tr><th>订单类型</th><th>用户</th><th>产品号</th><th>产品</th><th>状态</th><th>打样信息</th><th>提交时间</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="`${r.orderType}-${r.id}`"><td>{{ orderTypeText(r) }}</td><td>{{ r.username || `用户 ${r.userId}` }}</td><td>{{ r.productNo || '-' }}</td><td>{{ r.productName || r.title || r.assetTitle || '-' }}</td><td><span class="status" :class="{ success: r.samplePaymentStatus === 'paid' || r.status === 'processing' }">{{ textStatus(r) }}</span></td><td>{{ r.sampleMaterial || '-' }} · {{ money(r.sampleFeeYuan) }} · {{ r.sampleLeadTime || '待定' }}</td><td>{{ formatTime(r.createdAt) }}</td><td><button class="detail-button" @click="openDetail(r)">查看详情</button></td></tr></tbody></table><div v-if="!loading && !rows.length" class="empty">暂无订单</div></div>

    <div v-if="detailOpen" class="detail-mask" @click.self="closeDetail"><section class="detail-dialog" role="dialog" aria-modal="true" aria-label="订单详情"><header class="detail-head"><div><span>ORDER DETAIL</span><h2>{{ detail ? detailTitle() : '订单详情' }}</h2><small v-if="detail">{{ detail.productNo || detail.submissionNo || detail.requestNo || `订单 ${detail.id}` }} · {{ detail.orderType === 'professional' ? '专业作品打样' : orderTypeText(detail) }}</small></div><button class="close-button" @click="closeDetail">×</button></header><div v-if="detailLoading" class="detail-loading">正在读取订单关联信息…</div><main v-else-if="detail" class="detail-body">
      <section class="detail-grid"><article><h3>用户信息</h3><dl><dt>用户 ID</dt><dd>{{ detail.user?.userId || detail.userId || '-' }}</dd><dt>账号</dt><dd>{{ detail.user?.username || detail.username || '-' }}</dd><dt>电话</dt><dd>{{ detail.user?.phone || '-' }}</dd><dt>邮箱</dt><dd>{{ detail.user?.email || '-' }}</dd></dl></article><article><h3>订单状态</h3><dl><dt>当前阶段</dt><dd>{{ detail.samplePaymentStatus === 'paid' ? '已支付打样费 · 生产中' : detail.status || '-' }}</dd><dt>支付状态</dt><dd>{{ detail.samplePaymentStatus || '未涉及' }}</dd><dt>支付订单号</dt><dd>{{ detail.samplePaymentOrderNo || '-' }}</dd><dt>提交时间</dt><dd>{{ formatTime(detail.createdAt) }}</dd><dt>更新时间</dt><dd>{{ formatTime(detail.updatedAt) }}</dd></dl></article></section>
      <section class="detail-section"><h3>作品与文件</h3><div class="asset-row" v-if="detail.asset"><div><strong>{{ detail.asset.title || detail.asset.assetNo || '关联作品' }}</strong><span>{{ detail.asset.assetType === 'model' ? 'GLB 3D 模型' : '产品图片' }}</span></div><div class="file-actions"><a v-if="detail.asset.previewUrl" :href="detail.asset.previewUrl" target="_blank" rel="noopener">查看作品</a><a v-if="detail.asset.fileUrl" :href="detail.asset.fileUrl" target="_blank" rel="noopener">{{ detail.asset.assetType === 'model' ? '下载 GLB' : '打开原文件' }}</a></div></div><div v-if="isProfessional" class="asset-row"><div><strong>{{ detail.originalName || '专业 ZIP 作品包' }}</strong><span>ZIP · {{ fileSize(detail.fileSize) }}</span></div><a class="file-link" :href="detail.downloadUrl" target="_blank" rel="noopener">下载 ZIP 作品包</a></div><div v-if="detail.simulationImage?.previewUrl" class="simulation-preview"><strong>生产模拟图</strong><img :src="detail.simulationImage.previewUrl" alt="生产模拟图" /></div><div v-if="detail.multiviewImages?.length" class="multiview-grid"><figure v-for="image in detail.multiviewImages" :key="image.assetId"><img v-if="image.previewUrl" :src="image.previewUrl" :alt="image.label || image.view" /><figcaption>{{ image.label || image.view }} · 资产 {{ image.assetId }}</figcaption></figure></div><div v-if="!detail.asset && !isProfessional && !detail.multiviewImages?.length" class="muted">暂无可下载的关联文件</div></section>
      <section class="detail-section"><h3>申请与收货信息</h3><div class="info-lines"><p><b>产品：</b>{{ detail.productName || detail.sampleProductName || detail.title || '-' }} <b>材质：</b>{{ detail.material || detail.sampleMaterial || '-' }} <b>尺寸：</b>{{ detail.productSize || '-' }}</p><p><b>数量：</b>{{ detail.quantity || 1 }} <b>用途：</b>{{ detail.purpose || '-' }} <b>渠道：</b>{{ detail.museumName || '-' }}</p><p><b>收件人：</b>{{ detail.recipientName || '-' }} <b>电话：</b>{{ detail.recipientPhone || '-' }}</p><p><b>地址：</b>{{ detail.recipientAddress || '-' }}</p><p><b>用户说明：</b>{{ detail.note || '-' }}</p></div></section>
      <section class="edit-section"><h3>后台处理</h3><div class="edit-grid"><label>订单状态<select v-model="form.status" :disabled="!canEditQuote"><option value="review">待审核</option><option value="approved">已通过</option><option value="rejected">已驳回</option><option v-if="form.status === 'processing'" value="processing">生产中（支付自动进入）</option></select></label><label>打样价格（元）<input v-model="form.sampleFeeYuan" type="number" min="0" step="0.01" :disabled="!canEditQuote" /></label><label>预计交期<input v-model="form.sampleLeadTime" placeholder="例如：确认支付后 15 个工作日" :disabled="!canEditQuote" /></label><label>打样材质<input v-model="form.sampleMaterial" placeholder="填写生产材质" :disabled="!canEditQuote" /></label><label class="wide">报价说明<textarea v-model="form.sampleQuoteNote" rows="2" placeholder="费用包含内容、工艺和交付说明" :disabled="!canEditQuote" /></label><label class="wide">审核备注<textarea v-model="form.reviewComment" rows="2" placeholder="给用户或生产人员的处理备注" /></label></div><p v-if="!canEditQuote" class="locked-tip">该订单已进入支付流程，报价字段已锁定，避免修改已生成的支付金额。</p><div class="edit-actions"><button @click="closeDetail">关闭</button><button class="primary" :disabled="saving || !canEditQuote" @click="saveDetail">{{ saving ? '保存中…' : '保存订单信息' }}</button></div></section>
    </main></section></div>
  </div>
</template>

<style scoped>
.orders-page{padding:28px;color:#25372d}.orders-page header{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:18px}.orders-page header span,.detail-head span{font-size:11px;letter-spacing:2px;color:#72907b}.orders-page h1{margin:5px 0;font-size:28px}.orders-page p{margin:0;color:#718078}.orders-page button,.edit-actions button{border:0;border-radius:8px;background:#527b66;color:#fff;padding:9px 15px;font-weight:700;cursor:pointer}.orders-page button:disabled,.edit-actions button:disabled{opacity:.5;cursor:not-allowed}.table-wrap{overflow:auto;background:#fff;border:1px solid #e1e9e3;border-radius:10px}.table-wrap table{width:100%;min-width:1080px;border-collapse:collapse;font-size:13px}.table-wrap th,.table-wrap td{padding:13px 12px;border-bottom:1px solid #edf1ed;text-align:left;white-space:nowrap}.table-wrap th{background:#f6faf6;color:#567060}.status{color:#667a6b}.status.success{color:#3f7a51;font-weight:800}.detail-button{padding:6px 10px!important;font-size:12px}.empty{text-align:center;padding:50px;color:#819187}.detail-mask{position:fixed;z-index:100;inset:0;display:grid;place-items:center;padding:20px;background:rgba(25,42,31,.5)}.detail-dialog{display:flex;flex-direction:column;width:min(940px,100%);max-height:min(900px,calc(100dvh - 40px));overflow:hidden;border:1px solid #d8e5da;border-radius:14px;background:#fff;box-shadow:0 25px 80px rgba(18,40,24,.25)}.detail-head{display:flex;justify-content:space-between;align-items:flex-start;padding:20px 24px 15px;border-bottom:1px solid #edf2ed}.detail-head h2{margin:6px 0 4px;font-size:22px}.detail-head small{color:#84948a}.close-button{width:32px;height:32px;padding:0!important;border:1px solid #dce8de!important;background:#f7faf7!important;color:#718479!important;font-size:22px;line-height:1}.detail-body{min-height:0;overflow:auto;padding:20px 24px 24px}.detail-loading{padding:80px;text-align:center;color:#788b7e}.detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.detail-grid article,.detail-section,.edit-section{padding:15px;border:1px solid #e1eae2;border-radius:10px;background:#fbfdfb}.detail-grid h3,.detail-section h3,.edit-section h3{margin:0 0 11px;font-size:14px;color:#476452}.detail-grid dl{display:grid;grid-template-columns:90px minmax(0,1fr);margin:0;font-size:12px}.detail-grid dt,.detail-grid dd{padding:6px 0;border-bottom:1px solid #edf2ed}.detail-grid dt{color:#8a9b90}.detail-grid dd{margin:0;overflow-wrap:anywhere;color:#435c4b}.detail-section,.edit-section{margin-top:14px}.asset-row{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:10px 0;border-bottom:1px solid #edf2ed}.asset-row:last-of-type{border-bottom:0}.asset-row strong,.asset-row span{display:block}.asset-row strong{font-size:13px;color:#45604e}.asset-row span{margin-top:4px;color:#8b9a90;font-size:11px}.file-actions{display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end}.file-actions a,.file-link{padding:7px 9px;border-radius:7px;background:#eaf5ec;color:#427151;text-decoration:none;font-size:11px;font-weight:700}.simulation-preview{display:grid;gap:8px;margin-top:10px;color:#45604e;font-size:12px}.simulation-preview img{display:block;width:100%;max-height:280px;object-fit:contain;border:1px solid #e1eae2;border-radius:8px;background:#f3f7f3}.multiview-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:10px}.multiview-grid figure{margin:0;overflow:hidden;border:1px solid #e1eae2;border-radius:8px;background:#f3f7f3}.multiview-grid img{display:block;width:100%;height:130px;object-fit:contain}.multiview-grid figcaption{padding:6px;color:#728378;font-size:10px;text-align:center}.info-lines p{margin:7px 0;color:#607267;font-size:12px;line-height:1.6}.info-lines b{color:#415b4a}.muted,.locked-tip{color:#8c9c92;font-size:12px}.edit-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.edit-grid label{display:grid;gap:5px;color:#718378;font-size:11px}.edit-grid .wide{grid-column:1 / -1}.edit-grid input,.edit-grid select,.edit-grid textarea{width:100%;box-sizing:border-box;border:1px solid #d7e4d9;border-radius:7px;padding:8px 9px;background:#fff;color:#405748;font:inherit;font-size:12px}.edit-grid textarea{resize:vertical}.locked-tip{margin:10px 0 0}.edit-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:14px}.edit-actions button:first-child{border:1px solid #d8e4da;background:#fff;color:#6a7e70}.edit-actions .primary{background:#3f7053}@media(max-width:760px){.orders-page{padding:17px 12px}.detail-mask{padding:8px}.detail-head,.detail-body{padding-left:15px;padding-right:15px}.detail-grid,.edit-grid{grid-template-columns:1fr}.edit-grid .wide{grid-column:auto}.multiview-grid{grid-template-columns:1fr 1fr}}
</style>
